. /etc/patroni/appdb.env
{
  printf "\\set appdb_password '%s'\n" "$APPDB_PASSWORD"
  cat <<'ANTRIEB_SQL_ROLE_EOF'
SELECT format('CREATE ROLE appuser LOGIN PASSWORD %L', :'appdb_password')
WHERE NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'appuser') \gexec
SELECT format('ALTER ROLE appuser LOGIN PASSWORD %L', :'appdb_password') \gexec
SELECT 'CREATE DATABASE appdb OWNER appuser'
WHERE NOT EXISTS (SELECT 1 FROM pg_database WHERE datname = 'appdb') \gexec
ANTRIEB_SQL_ROLE_EOF
} | sudo -u postgres psql -v ON_ERROR_STOP=1 --no-psqlrc
unset APPDB_PASSWORD
sudo -u postgres psql -v ON_ERROR_STOP=1 --no-psqlrc -d appdb <<'ANTRIEB_SQL_DATA_EOF'
CREATE TABLE IF NOT EXISTS ha_evidence (
  id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  event text NOT NULL UNIQUE,
  writer text NOT NULL,
  created_at timestamptz NOT NULL DEFAULT clock_timestamp()
);
ALTER TABLE ha_evidence OWNER TO appuser;
INSERT INTO ha_evidence(event, writer)
VALUES ('initial-primary-node2', inet_server_addr()::text)
ON CONFLICT (event) DO NOTHING;
SELECT current_database() AS database, pg_is_in_recovery() AS in_recovery, current_setting('transaction_read_only') AS read_only;
SELECT id,event,writer FROM ha_evidence ORDER BY id;
ANTRIEB_SQL_DATA_EOF

